package com.stayos.database; import java.sql.*; public final class Database implements AutoCloseable { private final Connection c; public Database(String u)throws SQLException{c=DriverManager.getConnection(u);try(Statement s=c.createStatement()){s.executeUpdate("CREATE TABLE IF NOT EXISTS app_meta (key TEXT PRIMARY KEY,value TEXT NOT NULL)");s.executeUpdate("INSERT OR IGNORE INTO app_meta VALUES ('schema_version','1')");}} public String read(String k)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT value FROM app_meta WHERE key=?")){p.setString(1,k);try(ResultSet r=p.executeQuery()){return r.next()?r.getString(1):null;}}} public void write(String k,String v)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT OR REPLACE INTO app_meta VALUES (?,?)")){p.setString(1,k);p.setString(2,v);p.executeUpdate();}} public void close()throws SQLException{c.close();}}
